//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Values below one
    /// are treated as one attempt by `run_job`.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry configuration.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => return Err(error),
            Err(_) => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig::new(max_attempts, base_delay_ms, max_delay_ms)
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(3, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_the_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(2, 1, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 2);
        assert_eq!(sleeper.sleeps, vec![1]);
    }

    #[test]
    fn delay_multiplication_saturates_before_applying_the_cap() {
        let mut sleeper = FakeSleeper::default();

        let _ = run_job(&config(3, u64::MAX, u64::MAX), &mut sleeper, || {
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(sleeper.sleeps, vec![u64::MAX, u64::MAX]);
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` accepts a `RetryConfig`, a `Sleeper`, and a job closure. The
configuration uses `max_attempts` as the total number of calls, including the
first call. `Transient` errors are retried with delays of `base_delay_ms`, then
double after each retry, capped at `max_delay_ms`. `Permanent` errors return
immediately, and the final transient error is returned when the attempt budget
is exhausted.

For example:

```rust
use jobrunner::{run_job, RetryConfig, RetryError, Sleeper};

let config = RetryConfig::new(3, 100, 1_000);
# struct NoopSleeper;
# impl Sleeper for NoopSleeper { fn sleep_ms(&mut self, _: u64) {} }
let mut sleeper = NoopSleeper;
run_job(&config, &mut sleeper, || Ok::<(), RetryError>(()))?;
# Ok::<(), RetryError>(())
```
